from itertools import combinations

def solve(g):
    cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}
    placements=[]
    R=len(g); C=len(g[0])
    # squares
    for r in range(R-1):
      for c in range(C-1):
        s={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if s<=cells: placements.append((s,1,'square'))
    # L triominoes: 2x2 missing one corner; map color per missing corner
    colors={(r,c):col for r,c,col in []}
    # mapping missing TL->2, BL->3, TR->4, BR->? infer from demos? no BR orientation maybe color? likely color5 maybe pattern colors correspond rotations.
    for r in range(R-1):
      for c in range(C-1):
        block={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if len(block & cells)==3:
          miss=next(iter(block-cells))
          col={(r,c):2,(r+1,c):3,(r,c+1):4,(r+1,c+1):5}[miss]
          placements.append((block&cells,col,'L'))
    sols=[]
    def rec(rem, out, used):
      if not rem:
        sols.append(out.copy()); return
      x=min(rem, key=lambda p: sum(1 for s,_,_ in placements if p in s and s<=rem))
      for s,col,t in placements:
        if x in s and s<=rem:
          rec(rem-s,out+[(s,col)],used+[(s,col)])
    rec(cells,[],[])
    outs=[]
    for sol in sols:
      o=[[0]*C for _ in range(R)]
      for s,col in sol:
       for r,c in s:o[r][c]=col
      outs.append(o)
    return outs, sols

