def solve(g):
    cells={(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==8}; R=len(g); C=len(g[0]); placements=[]
    for r in range(R-1):
      for c in range(C-1):
        block={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if block<=cells: placements.append((block,1,'S'))
        for miss,col in [((r,c),2),((r+1,c),3),((r,c+1),4),((r+1,c+1),5)]:
          tri=block-{miss}
          if tri<=cells: placements.append((tri,col,'L'))
    sols=[]
    def rec(rem, out):
      if not rem: sols.append(out.copy()); return
      options=[(s,col) for s,col,_ in placements if s<=rem]
      x=min(rem,key=lambda p:sum(p in s for s,col in options))
      for s,col in options:
        if x in s: rec(rem-s,out+[(s,col)])
    rec(cells,[])
    outs=[]
    for sol in sols:
      o=[[0]*C for _ in range(R)]
      for s,col in sol:
       for r,c in s:o[r][c]=col
      outs.append(o)
    # unique outs
    unique={tuple(tuple(row) for row in o) for o in outs}
    return list(unique),sols
